// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BenchmarkRun) predicate.BenchmarkRun {
	return predicate.BenchmarkRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BenchmarkRun) predicate.BenchmarkRun {
	return predicate.BenchmarkRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BenchmarkRun) predicate.BenchmarkRun {
	return predicate.BenchmarkRun(sql.NotPredicates(p))
}
